This is a two-edged sword.  Then it becomes super easy to accidentally do:

```
var err error
var txn Transaction

// clean up on return
defer func() {
    if err != nil {
        result.Revert()
    }
}()

// correct
if txn, err = al.txnAllocClusterIPs(service, dryRun); err != nil {
    return nil, err
}
result = append(result, txn)

// broken!!
if txn, err := al.txnAllocNodePorts(service, dryRun); err != nil {
    return nil, err
}
result = append(result, txn)
```

The only difference is a sneaky `:`.

We could do something like:

```
var err error

// clean up on return
defer func() {
	if err != nil {
		result.Revert()
	}
}()
funcs := []func() (Transaction, error) {
	func() (Transaction, error) {
		return al.txnAllocClusterIPs(service, dryRun)
	},
	func() (Transaction, error) {
		return al.txnAllocNodePorts(service, dryRun)
	}
}

for _, fn := range funcs {
	var txn Transaction

	txn, err = fn()
	if err !=nil {
		return nil, err
	}
	result = append(result, txn)
}
```

but that feels equally convoluted.

What is your opinion?

Or:

```
result := metaTransaction{}
success := false

defer func() {
    if !success {
        result.Revert()
    }
}()

if txn, err := al.txnAllocClusterIPs(service, dryRun); err != nil {
    return nil, err
}
result = append(result, txn)

// broken!!
if txn, err := al.txnAllocNodePorts(service, dryRun); err != nil {
    return nil, err
}
result = append(result, txn)

success = true
return result
```

